import{_ as i,o as t,c as a,a6 as s}from"./chunks/framework.ZMCvXf1_.js";const k=JSON.parse('{"title":"Identity Management","description":"","frontmatter":{},"headers":[],"relativePath":"cli/identity.md","filePath":"cli/identity.md"}'),n={name:"cli/identity.md"};function o(r,e,d,h,l,c){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="identity-management" tabindex="-1">Identity Management <a class="header-anchor" href="#identity-management" aria-label="Permalink to “Identity Management”">​</a></h1><p>This guide covers noorm&#39;s cryptographic identity system — the keys that authenticate you to shared state, sign your changes, and let teammates encrypt vault secrets to you.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>noorm uses X25519 cryptographic identities for secure config sharing and audit tracking. Each identity is stored locally in <code>~/.noorm/identity.key</code> (private key) and <code>~/.noorm/identity.json</code> (metadata). The public key is derived deterministically from the private key, so it never has to be stored separately to be recovered.</p><p>A disk identity is hashed as <code>SHA-256(email + name + machine + os)</code>, where <code>machine</code> is the hostname. The same person on two laptops is therefore two identities in the audit trail, and each needs vault access propagated to it. Env-var identities hash differently on purpose, so a CI fleet reads as one user: see <a href="#env-var-identity-ci">Env-Var Identity (CI)</a> below.</p><p>For CI runners, identities load from environment variables instead of files — see the <a href="./../guide/automation/ci.html">CI automation guide</a> for end-to-end setup, including <code>noorm ci identity new</code> (generate keypair) and <code>noorm ci identity enroll</code> (grant vault access on a target database).</p><h2 id="creating-an-identity" tabindex="-1">Creating an Identity <a class="header-anchor" href="#creating-an-identity" aria-label="Permalink to “Creating an Identity”">​</a></h2><p>Run <code>noorm identity init</code> on your machine to create a keypair. <code>--name</code> and <code>--email</code> are both required; the command does not prompt.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Alice Cooper&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice@example.com</span></span></code></pre></div><p>This generates a keypair and writes:</p><ul><li>Private key: <code>~/.noorm/identity.key</code> (mode <code>0600</code>)</li><li>Public key: <code>~/.noorm/identity.pub</code> (mode <code>0644</code>)</li><li>Metadata: <code>~/.noorm/identity.json</code></li></ul><p>The private key never leaves your machine. Your public key is what teammates use to share encrypted state with you.</p><p>If an identity already exists, <code>init</code> refuses. Replacing it takes <code>--force --yes</code>, and it is destructive: state encryption is keyed off the private key, so every noorm project on the machine loses access to the configs, secrets, and database passwords in its <code>.noorm/state/state.enc</code>. Nothing re-encrypts existing state under the new key. noorm copies the old key files to <code>.bak-&lt;timestamp&gt;</code> siblings before overwriting, and aborts if it cannot. An ambient <code>NOORM_YES</code> does not satisfy this confirmation; only the literal <code>--yes</code> flag does.</p><h2 id="editing-your-identity" tabindex="-1">Editing Your Identity <a class="header-anchor" href="#editing-your-identity" aria-label="Permalink to “Editing Your Identity”">​</a></h2><p>Update the display name or email on the existing identity. At least one of <code>--name</code> or <code>--email</code> must be provided.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Alice Cooper&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;alice@newjob.com&quot;</span></span></code></pre></div><h2 id="exporting-your-public-key" tabindex="-1">Exporting Your Public Key <a class="header-anchor" href="#exporting-your-public-key" aria-label="Permalink to “Exporting Your Public Key”">​</a></h2><p>Print your public key so teammates can add you to encrypted vaults:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><h2 id="listing-known-identities" tabindex="-1">Listing Known Identities <a class="header-anchor" href="#listing-known-identities" aria-label="Permalink to “Listing Known Identities”">​</a></h2><p>Show every identity discovered from database syncs (the audit trail of who has touched shared state):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><h2 id="env-var-identity-ci" tabindex="-1">Env-Var Identity (CI) <a class="header-anchor" href="#env-var-identity-ci" aria-label="Permalink to “Env-Var Identity (CI)”">​</a></h2><p>When <code>NOORM_IDENTITY_PRIVATE_KEY</code>, <code>NOORM_IDENTITY_NAME</code>, and <code>NOORM_IDENTITY_EMAIL</code> are set at process startup, every <code>noorm</code> command in that process uses the env-derived identity without touching <code>~/.noorm/</code>.</p><p>The variables are read once when the process starts, so they apply to every command that process runs.</p><p><strong>Guarantees:</strong></p><ul><li>The public key is <strong>derived</strong> from the private key, not separately specified — same key, same public half.</li><li>The identity hash is <strong>independent of hostname or OS</strong> (CI uses <code>os=&#39;env&#39;</code>, <code>machine=publicKey</code>) — same key, same identity across every runner.</li><li>Env vars are <strong>trimmed automatically</strong> — leading/trailing whitespace is removed.</li><li><strong>Env vars win over disk</strong> — if both are present, env takes precedence.</li><li><strong>No files written</strong> — env-based bootstrap is read-only.</li></ul><p>To generate a CI-shaped keypair without touching the database, use <code>noorm ci identity new</code> (see the <a href="./../guide/automation/ci.html">CI automation guide</a>).</p>`,28)])])}const y=i(n,[["render",o]]);export{k as __pageData,y as default};
